package com.rtsbuilding.rtsbuilding.client.rendering.builder;
import com.rtsbuilding.rtsbuilding.client.screen.shape.ShapeDataRecords;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.RenderManager;import net.minecraft.client.renderer.vertex.DefaultVertexFormats;import net.minecraft.entity.Entity;import net.minecraft.util.EnumFacing;import net.minecraft.util.math.*;import org.lwjgl.opengl.GL11;import java.util.*;
/** 1.12 连锁破坏金色呼吸骨架。深度与穿透两遍均使用本类私有缓冲。 */
public final class UltimineGhostRenderer{
 private static final BufferBuilder DEPTH=new BufferBuilder(512*1024),NODEPTH=new BufferBuilder(512*1024),FILL=new BufferBuilder(512*1024);private static final WorldVertexBufferUploader UP=new WorldVertexBufferUploader();private UltimineGhostRenderer(){}
 static void render(ShapeDataRecords.GhostPreview p,BufferBuilder callerLine,BufferBuilder callerFill,float progress){if(p==null)return;Minecraft mc=Minecraft.getMinecraft();if(mc.objectMouseOver!=null&&mc.objectMouseOver.typeOfHit==RayTraceResult.Type.ENTITY&&mc.objectMouseOver.entityHit!=null){renderEntityBrackets(mc.objectMouseOver.entityHit);return;}List<BlockPos>outer=filterOuterBlocks(p.blocks());renderGeometry(UltimineBlockMerger.getEdgeLines(outer),outer,progress,.08F,1F);}
 static void renderGeometry(List<UltimineBlockMerger.EdgeLine>edges,List<BlockPos>fills,float progress,float fillAlpha,float alpha){if(edges==null||edges.isEmpty())return;float breath=(float)(.85+.15*Math.sin(System.currentTimeMillis()/1000D*.4*Math.PI));float r=lerp(1F*breath,.38F,progress),g=lerp(.72F*breath,1F,progress),b=lerp(.24F*breath,.42F,progress);RenderManager m=Minecraft.getMinecraft().getRenderManager();begin(DEPTH,GL11.GL_LINES);begin(NODEPTH,GL11.GL_LINES);begin(FILL,GL11.GL_QUADS);translate(DEPTH,m);translate(NODEPTH,m);translate(FILL,m);for(UltimineBlockMerger.EdgeLine e:edges){line(DEPTH,e,r,g,b,.95F*alpha);line(NODEPTH,e,r,g,b,.34F*alpha);}if(fills!=null)for(BlockPos q:fills)RenderGlobal.addChainedFilledBoxVertices(FILL,q.getX(),q.getY(),q.getZ(),q.getX()+1,q.getY()+1,q.getZ()+1,r,g,b,fillAlpha*alpha);draw(false);}
 private static void begin(BufferBuilder b,int mode){b.begin(mode,DefaultVertexFormats.POSITION_COLOR);}private static void translate(BufferBuilder b,RenderManager m){b.setTranslation(-m.viewerPosX,-m.viewerPosY,-m.viewerPosZ);}private static void line(BufferBuilder b,UltimineBlockMerger.EdgeLine e,float r,float g,float bl,float a){b.pos(e.x1(),e.y1(),e.z1()).color(r,g,bl,a).endVertex();b.pos(e.x2(),e.y2(),e.z2()).color(r,g,bl,a).endVertex();}
 private static void draw(boolean brackets){GlSnapshot gl=GlSnapshot.capture();try{GlStateManager.enableBlend();GlStateManager.disableTexture2D();GlStateManager.depthMask(false);UP.draw(DEPTH);GlStateManager.disableDepth();UP.draw(NODEPTH);GlStateManager.enableDepth();UP.draw(FILL);}finally{DEPTH.setTranslation(0,0,0);NODEPTH.setTranslation(0,0,0);FILL.setTranslation(0,0,0);gl.restore();}}
 static void renderPass1(List<UltimineBlockMerger.EdgeLine>e,BufferBuilder c,float r,float g,float b){renderPass1(e,c,r,g,b,.95F);}static void renderPass1(List<UltimineBlockMerger.EdgeLine>e,BufferBuilder c,float r,float g,float b,float a){renderGeometry(e,Collections.<BlockPos>emptyList(),0,0,a);}static void renderPass2(List<UltimineBlockMerger.EdgeLine>e,float r,float g,float b,float a){renderGeometry(e,Collections.<BlockPos>emptyList(),0,0,a);}static void renderFill(List<BlockPos>b,BufferBuilder c,float r,float g,float bl,float a){renderGeometry(UltimineBlockMerger.getEdgeLines(b),b,0,a,0);}
 private static void renderEntityBrackets(Entity e){AxisAlignedBB a=e.getEntityBoundingBox().grow(.03);List<BlockPos>none=Collections.emptyList();List<UltimineBlockMerger.EdgeLine>edges=new ArrayList<UltimineBlockMerger.EdgeLine>();double x=a.minX,X=a.maxX,y=a.minY,Y=a.maxY,z=a.minZ,Z=a.maxZ;edges.add(new UltimineBlockMerger.EdgeLine(x,y,z,X,y,z));edges.add(new UltimineBlockMerger.EdgeLine(X,y,z,X,y,Z));edges.add(new UltimineBlockMerger.EdgeLine(X,y,Z,x,y,Z));edges.add(new UltimineBlockMerger.EdgeLine(x,y,Z,x,y,z));edges.add(new UltimineBlockMerger.EdgeLine(x,Y,z,X,Y,z));edges.add(new UltimineBlockMerger.EdgeLine(X,Y,z,X,Y,Z));edges.add(new UltimineBlockMerger.EdgeLine(X,Y,Z,x,Y,Z));edges.add(new UltimineBlockMerger.EdgeLine(x,Y,Z,x,Y,z));edges.add(new UltimineBlockMerger.EdgeLine(x,y,z,x,Y,z));edges.add(new UltimineBlockMerger.EdgeLine(X,y,z,X,Y,z));edges.add(new UltimineBlockMerger.EdgeLine(X,y,Z,X,Y,Z));edges.add(new UltimineBlockMerger.EdgeLine(x,y,Z,x,Y,Z));renderGeometry(edges,none,0,0,1);}
 private static List<BlockPos>filterOuterBlocks(List<BlockPos>b){if(b==null)return Collections.emptyList();Set<BlockPos>s=new HashSet<BlockPos>(b);List<BlockPos>o=new ArrayList<BlockPos>();for(BlockPos p:b)for(EnumFacing f:EnumFacing.values())if(!s.contains(p.offset(f))){o.add(p);break;}return o;}private static float lerp(float a,float b,float t){t=Math.max(0,Math.min(1,t));return a+(b-a)*t;}
 static final class GlSnapshot{final boolean blend,texture,depth,cull,depthMask;final int src,dst,textureBinding;private GlSnapshot(boolean b,boolean t,boolean d,boolean c,boolean m,int s,int x,int binding){blend=b;texture=t;depth=d;cull=c;depthMask=m;src=s;dst=x;textureBinding=binding;}static GlSnapshot capture(){return new GlSnapshot(GL11.glIsEnabled(GL11.GL_BLEND),GL11.glIsEnabled(GL11.GL_TEXTURE_2D),GL11.glIsEnabled(GL11.GL_DEPTH_TEST),GL11.glIsEnabled(GL11.GL_CULL_FACE),GL11.glGetBoolean(GL11.GL_DEPTH_WRITEMASK),GL11.glGetInteger(GL11.GL_BLEND_SRC),GL11.glGetInteger(GL11.GL_BLEND_DST),GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D));}void restore(){set(GL11.GL_BLEND,blend);set(GL11.GL_TEXTURE_2D,texture);set(GL11.GL_DEPTH_TEST,depth);set(GL11.GL_CULL_FACE,cull);GL11.glDepthMask(depthMask);GL11.glBlendFunc(src,dst);GL11.glBindTexture(GL11.GL_TEXTURE_2D,textureBinding);}private static void set(int cap,boolean enabled){if(enabled)GL11.glEnable(cap);else GL11.glDisable(cap);}}
}
